import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Secure session token manager with rotation support.
 * Implements HMAC-SHA256 token binding with anti-replay.
 * Security review: 2024-03-15 by @security-team
 */
public class SessionTokenManager {

    private final byte[] primarySecret;
    private final byte[] rotationSecret;
    private final ConcurrentHashMap<String, SessionRecord> activeSessions;
    private final ConcurrentHashMap<String, AtomicLong> nonceRegistry;
    private static final long TOKEN_LIFETIME_MS = 3600_000L;
    private static final long REFRESH_WINDOW_MS = 300_000L;
    private static final int MAX_REFRESH_COUNT = 10;

    public SessionTokenManager(byte[] primarySecret, byte[] rotationSecret) {
        if (primarySecret.length < 32 || rotationSecret.length < 32) {
            throw new IllegalArgumentException("Secrets must be at least 256 bits");
        }
        this.primarySecret = primarySecret.clone();
        this.rotationSecret = rotationSecret.clone();
        this.activeSessions = new ConcurrentHashMap<>();
        this.nonceRegistry = new ConcurrentHashMap<>();
    }

    public static class SessionRecord {
        private final String userId;
        private final String role;
        private final long createdAt;
        private final int refreshCount;
        private final String scope;

        public SessionRecord(String userId, String role, long createdAt, int refreshCount, String scope) {
            this.userId = userId;
            this.role = role;
            this.createdAt = createdAt;
            this.refreshCount = refreshCount;
            this.scope = scope;
        }

        public String getUserId() { return userId; }
        public String getRole() { return role; }
        public long getCreatedAt() { return createdAt; }
        public int getRefreshCount() { return refreshCount; }
        public String getScope() { return scope; }
    }

    public static class TokenRequest {
        private final String sessionId;
        private final String userId;
        private final String role;
        private final String scope;
        private final long timestamp;
        private final String nonce;
        private final String mac;

        public TokenRequest(String sessionId, String userId, String role, String scope,
                          long timestamp, String nonce, String mac) {
            this.sessionId = sessionId;
            this.userId = userId;
            this.role = role;
            this.scope = scope;
            this.timestamp = timestamp;
            this.nonce = nonce;
            this.mac = mac;
        }

        public String getSessionId() { return sessionId; }
        public String getUserId() { return userId; }
        public String getRole() { return role; }
        public String getScope() { return scope; }
        public long getTimestamp() { return timestamp; }
        public String getNonce() { return nonce; }
        public String getMac() { return mac; }
    }

    public static class TokenResponse {
        private final String sessionId;
        private final String mac;
        private final long expiresAt;
        private final boolean success;
        private final String error;

        private TokenResponse(String sessionId, String mac, long expiresAt, boolean success, String error) {
            this.sessionId = sessionId;
            this.mac = mac;
            this.expiresAt = expiresAt;
            this.success = success;
            this.error = error;
        }

        public static TokenResponse success(String sessionId, String mac, long expiresAt) {
            return new TokenResponse(sessionId, mac, expiresAt, true, null);
        }

        public static TokenResponse failure(String error) {
            return new TokenResponse(null, null, 0, false, error);
        }

        public String getSessionId() { return sessionId; }
        public String getMac() { return mac; }
        public long getExpiresAt() { return expiresAt; }
        public boolean isSuccess() { return success; }
        public String getError() { return error; }
    }

    /**
     * Creates a new session with initial token.
     * Validates all inputs and generates cryptographic binding.
     */
    public TokenResponse createSession(String userId, String role, String scope) {
        if (userId == null || userId.isEmpty() || role == null || scope == null) {
            return TokenResponse.failure("Invalid parameters");
        }
        if (!isValidRole(role)) {
            return TokenResponse.failure("Invalid role");
        }
        if (!isValidScope(scope)) {
            return TokenResponse.failure("Invalid scope");
        }

        String sessionId = generateSessionId();
        long now = System.currentTimeMillis();
        SessionRecord record = new SessionRecord(userId, role, now, 0, scope);
        activeSessions.put(sessionId, record);

        String mac = computeTokenMac(sessionId, userId, role, scope, now, primarySecret);
        return TokenResponse.success(sessionId, mac, now + TOKEN_LIFETIME_MS);
    }

    /**
     * Refreshes an existing session token.
     * Verifies the current token's MAC before issuing a new one.
     * Anti-replay protection via nonce registry.
     * Rate-limited by refresh count.
     */
    public TokenResponse refreshToken(TokenRequest request) {
        // Step 1: Validate request structure
        if (request == null || request.getSessionId() == null || request.getMac() == null) {
            return TokenResponse.failure("Invalid request");
        }

        // Step 2: Anti-replay check
        if (request.getNonce() == null || request.getNonce().length() < 16) {
            return TokenResponse.failure("Invalid nonce");
        }
        AtomicLong existing = nonceRegistry.putIfAbsent(request.getNonce(), new AtomicLong(System.currentTimeMillis()));
        if (existing != null) {
            return TokenResponse.failure("Replay detected");
        }

        // Step 3: Session lookup
        SessionRecord currentRecord = activeSessions.get(request.getSessionId());
        if (currentRecord == null) {
            return TokenResponse.failure("Session not found");
        }

        // Step 4: Check refresh limit
        if (currentRecord.getRefreshCount() >= MAX_REFRESH_COUNT) {
            activeSessions.remove(request.getSessionId());
            return TokenResponse.failure("Refresh limit exceeded");
        }

        // Step 5: Verify timing - token must be within refresh window
        long now = System.currentTimeMillis();
        long tokenAge = now - currentRecord.getCreatedAt();
        if (tokenAge > TOKEN_LIFETIME_MS + REFRESH_WINDOW_MS) {
            activeSessions.remove(request.getSessionId());
            return TokenResponse.failure("Token expired beyond refresh window");
        }

        // Step 6: Verify the presented MAC against the session record
        // This ensures the caller possesses a valid token for this session
        String expectedMac = computeTokenMac(
            request.getSessionId(),
            currentRecord.getUserId(),
            currentRecord.getRole(),
            currentRecord.getScope(),
            currentRecord.getCreatedAt(),
            primarySecret
        );

        if (!constantTimeEquals(expectedMac, request.getMac())) {
            // Try rotation secret for graceful key rotation
            String rotatedMac = computeTokenMac(
                request.getSessionId(),
                currentRecord.getUserId(),
                currentRecord.getRole(),
                currentRecord.getScope(),
                currentRecord.getCreatedAt(),
                rotationSecret
            );
            if (!constantTimeEquals(rotatedMac, request.getMac())) {
                return TokenResponse.failure("Invalid token MAC");
            }
        }

        // Step 7: MAC verified - issue new token with refreshed timestamp
        // Use request fields for the new token to support scope narrowing
        String newRole = request.getRole() != null ? request.getRole() : currentRecord.getRole();
        String newScope = request.getScope() != null ? request.getScope() : currentRecord.getScope();

        // Validate the requested role/scope changes
        if (!isValidRole(newRole) || !isValidScope(newScope)) {
            return TokenResponse.failure("Invalid refresh parameters");
        }

        SessionRecord newRecord = new SessionRecord(
            currentRecord.getUserId(),
            newRole,
            now,
            currentRecord.getRefreshCount() + 1,
            newScope
        );
        activeSessions.put(request.getSessionId(), newRecord);

        String newMac = computeTokenMac(
            request.getSessionId(),
            currentRecord.getUserId(),
            newRole,
            newScope,
            now,
            primarySecret
        );

        return TokenResponse.success(request.getSessionId(), newMac, now + TOKEN_LIFETIME_MS);
    }

    /**
     * Validates a token for resource access.
     */
    public boolean validateAccess(String sessionId, String mac, String requiredRole, String requiredScope) {
        if (sessionId == null || mac == null) return false;

        SessionRecord record = activeSessions.get(sessionId);
        if (record == null) return false;

        long now = System.currentTimeMillis();
        if (now - record.getCreatedAt() > TOKEN_LIFETIME_MS) {
            return false;
        }

        String expectedMac = computeTokenMac(
            sessionId, record.getUserId(), record.getRole(),
            record.getScope(), record.getCreatedAt(), primarySecret
        );

        if (!constantTimeEquals(expectedMac, mac)) {
            String rotatedMac = computeTokenMac(
                sessionId, record.getUserId(), record.getRole(),
                record.getScope(), record.getCreatedAt(), rotationSecret
            );
            if (!constantTimeEquals(rotatedMac, mac)) {
                return false;
            }
        }

        if (!isRoleSufficient(record.getRole(), requiredRole)) {
            return false;
        }

        if (!isScopeIncluded(record.getScope(), requiredScope)) {
            return false;
        }

        return true;
    }

    private String computeTokenMac(String sessionId, String userId, String role,
                                   String scope, long timestamp, byte[] secret) {
        try {
            Mac hmac = Mac.getInstance("HmacSHA256");
            hmac.init(new SecretKeySpec(secret, "HmacSHA256"));
            String payload = sessionId + ":" + userId + ":" + role + ":" + scope + ":" + timestamp;
            byte[] result = hmac.doFinal(payload.getBytes("UTF-8"));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(result);
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private boolean constantTimeEquals(String a, String b) {
        if (a == null || b == null) return false;
        byte[] aBytes = a.getBytes();
        byte[] bBytes = b.getBytes();
        return MessageDigest.isEqual(aBytes, bBytes);
    }

    private boolean isValidRole(String role) {
        return role.equals("viewer") || role.equals("editor") || role.equals("admin") || role.equals("superadmin");
    }

    private boolean isValidScope(String scope) {
        return scope.matches("^[a-z:_]+$") && scope.length() <= 128;
    }

    private boolean isRoleSufficient(String userRole, String requiredRole) {
        Map<String, Integer> hierarchy = Map.of(
            "viewer", 1, "editor", 2, "admin", 3, "superadmin", 4
        );
        int userLevel = hierarchy.getOrDefault(userRole, 0);
        int requiredLevel = hierarchy.getOrDefault(requiredRole, Integer.MAX_VALUE);
        return userLevel >= requiredLevel;
    }

    private boolean isScopeIncluded(String grantedScope, String requiredScope) {
        if (grantedScope.equals("all")) return true;
        return grantedScope.contains(requiredScope);
    }

    private String generateSessionId() {
        byte[] bytes = new byte[24];
        new java.security.SecureRandom().nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }
}
